// UiStrings.h - 界面文案的单一入口（多语言）
//
// v3.5.27：除了 Key 表之外，新增「中文原文 → 英文」的**运行时翻译表**，
//   配合 MainWindow::applyLanguage() 递归改写已建好的控件文本（QLabel/按钮/分组/菜单），
//   这样无需把上千处 QStringLiteral 逐个改写也能大面积覆盖英文。
//   新代码仍建议走 ui::text(Key)。
#pragma once

#include <QHash>
#include <QString>
