inline Language& currentLanguageRef()
{
    static Language lang = Language::Chinese;
    return lang;
}

inline void setLanguage(Language lang) { currentLanguageRef() = lang; }
inline Language language() { return currentLanguageRef(); }
inline bool isEnglish() { return currentLanguageRef() == Language::English; }

inline QString text(Key k)
{
    const QStringList& t = table(language());
    const int idx = static_cast<int>(k);
    if (idx >= 0 && idx < t.size()) return t.at(idx);
    return QString();
}

// 中文原文 → 当前语言（找不到就原样返回）
inline QString tr(const QString& zh)
{
    if (!isEnglish()) return zh;
    const auto it = zhToEn().constFind(zh);
    return it != zhToEn().constEnd() ? it.value() : zh;
}

